from core import *

@register('differentiation','hilbert-representer-bound','derivative-functional-Hilbert-space-norm','Riesz-representer-and-Cauchy-Schwarz','A sharp derivative bound under an integral-square constraint requires the correct representer in the constrained polynomial space and an equality case.','Chebyshev alternation concerns a uniform norm; this is a different inner-product geometry with explicit side constraints.',[{'caseId':'degree-'+str(N)+'-order-'+str(order)+'-point-'+str(point)+'-'+side,'N':N,'order':order,'point':str(point),'side':side,'purpose':'Change derivative order, evaluation location, or the allowed polynomial subspace.'} for N,order,point,side in [(3,1,0,'none'),(4,1,R(1,2),'none'),(4,2,0,'none'),(5,1,1,'none'),(5,2,R(-1,2),'none'),(6,1,R(1,2),'zero-mean'),(6,2,0,'zero-at-zero'),(7,1,R(1,3),'zero-at-zero')]],['polynomial differentiation','inner products','Cauchy-Schwarz','equality conditions'])
def riesz(case):
 N=case['N'];order=case['order'];point=R(case['point']);side=case['side']
 if side=='none':basis=[x**j for j in range(N+1)];constraint=''
 elif side=='zero-at-zero':basis=[x**j for j in range(1,N+1)];constraint=r',\quad p(0)=0'
 else:basis=[x**j-s.integrate(x**j,(x,-1,1))/2 for j in range(1,N+1)];constraint=r',\quad\int_{-1}^1p(x)\,\mathrm{d}x=0'
 G=s.Matrix([[s.integrate(a*b,(x,-1,1)) for b in basis] for a in basis]);ell=s.Matrix([s.diff(b,x,order).subs(x,point) for b in basis]);weights=G.inv()*ell;K=s.expand(sum(a*b for a,b in zip(weights,basis)));norm=s.factor((ell.T*weights)[0]);ans=s.sqrt(norm)
 for j,b in enumerate(basis):ck('The displayed representer acts correctly on basis element '+str(j),s.integrate(K*b,(x,-1,1)),s.diff(b,x,order).subs(x,point))
 ck('Independent polynomial integration evaluates the squared representer norm',s.integrate(s.expand(K*K),(x,-1,1)),norm)
 ck('The normalized extremizer attains the requested derivative',s.diff(K/ans,x,order).subs(x,point),ans)
 condition('The representer is nonzero and the norm positive',norm>0,'The requested derivative is a nonzero functional on the stated finite-dimensional space.')
 if side=='zero-at-zero':ck('The extremizer obeys the point constraint',K.subs(x,0),0)
 if side=='zero-mean':ck('The extremizer obeys the mean constraint',s.integrate(K,(x,-1,1)),0)
 analytic('Sharp representer norm',['The polynomial degree, side constraint, and real evaluation point are exactly as displayed.'],['The verified polynomial K belongs to the admissible linear subspace and satisfies integral(Kp)=the requested derivative for every basis vector, hence for every admissible polynomial.','Cauchy-Schwarz bounds the absolute derivative by sqrt(integral K^2)*sqrt(integral p^2).','The admissible polynomial K/sqrt(integral K^2) has unit norm and achieves the bound, proving the maximum rather than merely an upper estimate.'])
 return candidate(T('Among real polynomials satisfying ')+r'\deg p\le'+str(N)+constraint+r',\quad\int_{-1}^1p(x)^2\,\mathrm{d}x\le1,'+T(' find the largest possible value of ')+r'|p^{('+str(order)+r')}('+L(point)+r')|.',ans,[(norm,'Return the squared norm instead of its square root'),(1/ans,'Invert the functional norm'),(ans/2,'Divide by the interval length after normalizing the integral'),(ans/s.sqrt(2),'Use normalized average measure in only one of the two norms'),(ans*s.sqrt(2),'Replace the stated integral bound by an average bound'),(2*ans,'Multiply by the interval length instead of using the given norm')],[T('Find a polynomial representing this derivative as an inner product on the stated admissible space.'),r'K(x)='+L(K),r'\int_{-1}^1K(x)p(x)\,\mathrm{d}x=p^{('+str(order)+r')}('+L(point)+r'),\qquad\int_{-1}^1K(x)^2\,\mathrm{d}x='+L(norm),T('The first identity can be checked on a basis of the stated polynomial space, including its side constraint.'),r'|p^{('+str(order)+r')}('+L(point)+r')|\le\left(\int_{-1}^1K^2\right)^{1/2}\left(\int_{-1}^1p^2\right)^{1/2}\le'+L(ans),r'p(x)=\frac{K(x)}{'+L(ans)+r'}\quad\textnormal{is admissible and attains equality.}'],'sharp-polynomial-derivative-L2-representer')

@register('differentiation','eigenvalue-curvature','simple-eigenvalue-perturbation','normalized-eigenvector-differentiation','The moving eigenvalue branch requires a normalization of its eigenvector; every off-diagonal coupling contributes with its signed spectral gap.','A derivative of the whole determinant does not select or normalize a particular moving eigenvalue.',[{'caseId':'matrix-'+str(i),'diag':D,'off':off,'diagB':db,'j':j,'purpose':'Vary the chosen spectral branch, gap signs, and coupling geometry.'} for i,(D,off,db,j) in enumerate([([-3,1,4],[1,2,3],[1,0,-1],0),([-3,1,4],[1,2,3],[0,2,1],1),([-4,-1,2],[2,1,3],[1,-1,2],2),([-2,1,5],[3,-1,2],[-1,1,0],1),([-5,0,3],[1,-2,1],[2,1,-1],0),([-4,2,7],[2,3,-1],[0,-1,1],2),([-3,2,6],[3,1,-2],[1,2,0],1),([-6,-1,4],[2,-3,1],[-2,0,1],2)])],['implicit-function theorem','matrix eigenvalues','second derivatives'])
def eigen(case):
 ds=list(map(s.Integer,case['diag']));bs=list(map(s.Integer,case['diagB']));o=list(map(s.Integer,case['off']));j=case['j'];D=s.diag(*ds);B=s.Matrix([[bs[0],o[0],o[1]],[o[0],bs[1],o[2]],[o[1],o[2],bs[2]]]);M=D+t*B;gapTerms=[B[j,q]**2/(ds[j]-ds[q]) for q in range(3) if q!=j];A=2*sum(gapTerms)
 P=s.expand((z*s.eye(3)-M).det());p0={t:0,z:ds[j]};der1=bs[j]
 oracle=-(s.diff(P,t,2)+2*s.diff(P,t,z)*der1+s.diff(P,z,2)*der1**2).subs(p0)/s.diff(P,z).subs(p0)
 ck('Independent characteristic-polynomial implicit differentiation gives the curvature',oracle,A)
 condition('The root is simple at the initial parameter',s.diff(P,z).subs(p0)!=0,'All three diagonal entries are distinct, so the local real eigenvalue branch exists uniquely.')
 for q in range(3):
  if q!=j:ck('The differentiated eigenvector equation for component '+str(q+1),(ds[q]-ds[j])*(B[q,j]/(ds[j]-ds[q]))+B[q,j],0)
 analytic('Simple symmetric eigenvalue branch',['The displayed matrix is real symmetric for real t, and the chosen initial eigenvalue is simple.'],['Normalize the local eigenvector so its selected component equals one. At zero it is the corresponding coordinate vector.','Differentiate the other component equations to get v_k prime=B_kj/(d_j-d_k). The selected row gives lambda prime=B_jj.','Differentiate that row again: lambda second=2 sum B_jk v_k prime. The characteristic-polynomial calculation independently verifies the complete result.'])
 absSum=2*sum(abs(v) for v in gapTerms);linear=2*sum(B[j,q]/(ds[j]-ds[q]) for q in range(3) if q!=j);squared=2*sum(B[j,q]**2/(ds[j]-ds[q])**2 for q in range(3) if q!=j)
 return candidate(r'A(t)='+L(M)+r'.'+T('Let the real eigenvalue branch near zero be defined by ')+r'\lambda(0)='+L(ds[j])+r'.'+T(' Find ')+r'\lambda^{\prime\prime}(0).',A,[(A/2,'Omit the factor two from the two differentiated couplings'),(-A,'Reverse every spectral gap'),(absSum,'Replace signed spectral gaps by their absolute values'),(-absSum,'Give every coupling the negative sign'),(linear,'Fail to square each off-diagonal coupling'),(squared,'Square the spectral-gap denominator incorrectly'),(A+bs[j]**2,'Add a diagonal second-order term although the diagonal perturbation is affine')],[r'D=A(0)=\operatorname{diag}(d_1,d_2,d_3),\quad B=A\prime(0),\quad j='+str(j+1)+r',\quad d_j='+L(ds[j]),T('Normalize the local eigenvector by setting its selected coordinate to one. Its other coordinates vanish at the initial parameter.'),r'v_k\prime(0)=\frac{B_{kj}}{d_j-d_k}\quad(k\ne j),\qquad\lambda\prime(0)=B_{jj}',r'\lambda^{\prime\prime}(0)=2\sum_{k\ne j}\frac{B_{jk}^2}{d_j-d_k}=2\left('+r'+'.join(r'\left('+L(v)+r'\right)' for v in gapTerms)+r'\right)='+L(A),T('The initial eigenvalue is simple, so the branch and this differentiation are well defined.')],'signed-gap-simple-eigenvalue-curvature')

@register('differentiation','implicit-root-trace','moving-root-symmetric-trace','quotient-algebra-trace-and-implicit-differentiation','Implicit root derivatives are individually algebraic, but a symmetric sum can be found exactly through a polynomial remainder trace.','The Lagrange family follows one analytic root; this construction exploits cancellation across every complex root.',[{'caseId':'degree-'+str(N)+'-perturbation-'+str(q),'N':N,'q':q,'purpose':'Different polynomial degrees and perturbation directions; no explicit root solving is supplied.'} for N in [5,6,7,8] for q in [0,1]],['simple roots','implicit differentiation','polynomial remainders','Lagrange interpolation'])
def root_trace(case):
 N=case['N'];q=case['q'];P=x**N-x-1;Q=x**q;U=s.invert(s.diff(P,x),P,x);V=s.rem(Q*Q*U,P,x);A=s.expand(V).coeff(x,N-1)
 C=s.zeros(N)
 for j in range(N-1):C[j+1,j]=1
 for j in range(N):C[j,N-1]=-s.expand(P).coeff(x,j)
 Pinv=(N*C**(N-1)-s.eye(N)).inv();Rmat=C**q*Pinv
 ck('Independent companion-matrix trace of squared root sensitivities',s.trace(Rmat*Rmat),A)
 ck('The displayed polynomial inverse is exact modulo the root polynomial',s.rem(s.diff(P,x)*U,P,x),1)
 condition('Every root is simple',s.gcd(P,s.diff(P,x))==1,'A common root would be -N/(N-1), contradicting its derivative-implied magnitude below one.')
 analytic('Remainder trace identity',['All roots are simple and all local analytic branches are counted, including nonreal branches.'],['Implicit differentiation gives r_i prime=Q(r_i)/P prime(r_i).','For any polynomial remainder H of degree below N, Lagrange interpolation makes its leading coefficient equal sum H(r_i)/P prime(r_i).','Taking H congruent to Q^2/P prime modulo P gives the desired sum of squared derivatives as that leading coefficient. A companion-matrix trace verifies the result independently.'])
 return candidate(r'P_t(z)=z^{'+str(N)+r'}-z-1-tz^{'+str(q)+r'}.'+T('Let its '+str(N)+' simple complex roots at zero continue as local analytic branches ')+r'r_1(t),\ldots,r_{'+str(N)+r'}(t).'+T('Find ')+r'\sum_{i=1}^{'+str(N)+r'}(r_i\prime(0))^2.',A,[(A/N,'Return the average instead of the sum'),(N*A,'Multiply the trace by the number of roots again'),(-A,'Keep an erroneous sign after squaring root sensitivities'),(A/2,'Insert a Taylor-factorial factor into a sum of first derivatives'),(2*A,'Count each complex root together with an additional conjugate'),(s.Integer(0),'Confuse the sum of squares with the square of the sum')],[r'P(z)=z^{'+str(N)+r'}-z-1,\quad Q(z)=z^{'+str(q)+r'},\qquad r_i\prime(0)=\frac{Q(r_i(0))}{P\prime(r_i(0))}',T('The roots are simple. To sum their rational functions without solving them, use the leading coefficient in Lagrange interpolation.'),r'[z^{'+str(N-1)+r'}]H(z)=\sum_{P(r)=0}\frac{H(r)}{P\prime(r)}\quad(\deg H<'+str(N)+r')',r'U(z)='+L(U.subs(x,z))+r',\qquad P\prime(z)U(z)\equiv1\pmod{P(z)}',r'V(z)=\operatorname{rem}(Q(z)^2U(z),P(z))='+L(V.subs(x,z)),T('Here rem is the polynomial remainder, and brackets extract a coefficient. Substitute this remainder into the interpolation identity.'),r'\sum_i(r_i\prime(0))^2=[z^{'+str(N-1)+r'}]V(z)='+L(A)],'implicit-all-root-derivative-square-trace')

@register('differentiation','log-derivative-root-count','real-rooted-logarithmic-derivative-interlacing','pole-monotonicity-and-inherited-multiplicity','Count inherited zeros separately from zeros between poles; the sign of the perturbation determines which exterior interval supplies the final zero.','A local product logarithmic derivative gives a value at one point, whereas this uses its global monotonicity and pole behavior.',[{'caseId':'multiplicities-'+str(i),'roots':roots,'mult':mult,'c':c,'purpose':'Vary repeated roots and the exterior interval selected by the sign.'} for i,(roots,mult,c) in enumerate([([-2,0,3],[1,2,3],1),([-3,1,4],[2,1,2],-2),([-4,-1,2,5],[1,1,1,2],3),([-3,0,2,6],[3,2,1,1],-1),([-5,-2,1],[4,3,2],2),([-4,0,3,7],[2,2,2,2],-3),([-2,1,4,8,9],[1,2,1,3,1],1),([-7,-3,0,2,5],[2,1,3,1,2],-2)])],['polynomial multiplicity','logarithmic derivative','intermediate value theorem'])
def root_count(case):
 roots=case['roots'];mult=case['mult'];c=s.Integer(case['c']);P=s.prod((x-r)**a for r,a in zip(roots,mult));F=s.diff(P,x)-c*P;A=s.Integer(len(roots)+sum(a>1 for a in mult));factor=s.prod((x-r)**(a-1) for r,a in zip(roots,mult));res=s.cancel(F/factor)
 ck('Factoring out every inherited multiplicity leaves a degree equal to the number of poles',s.degree(res,x),len(roots))
 # Exact Sturm count is independent of the interval proof and counts distinct real roots of the squarefree polynomial.
 squarefree=s.Poly(F,x).sqf_part();ck('Independent exact Sturm count of distinct real roots',squarefree.count_roots(-s.oo,s.oo),A)
 for r,a in zip(roots,mult):condition('Residual does not introduce a zero at pole '+str(r),res.subs(x,r)!=0,'The original root has exactly multiplicity one less after applying derivative minus c times the polynomial.')
 analytic('Monotonic logarithmic derivative',['The displayed roots are distinct real numbers, their multiplicities are positive integers, and c is nonzero.'],['Away from the roots, P prime/P=sum m_j/(x-r_j) has strictly negative derivative. It decreases from plus infinity to minus infinity between neighboring poles, producing exactly one solution of P prime/P=c in each gap.','On the right exterior interval the range is all positive values, and on the left it is all negative values. Exactly one exterior interval contributes, according to the sign of c.','At each repeated root the derivative equation retains a zero of multiplicity m_j-1. Count each such location once because the problem requests distinct roots.'])
 degree=sum(mult);repeat=sum(a>1 for a in mult)
 return candidate(r'P(x)='+L(P)+r'.'+T('How many distinct real solutions does the equation ')+r'P\prime(x)='+L(c)+r'P(x)'+T(' have?'),A,[(degree,'Count multiplicities rather than distinct solutions'),(s.Integer(len(roots)),'Omit every inherited repeated root'),(s.Integer(len(roots)-1),'Count only the bounded gaps'),(s.Integer(repeat),'Count only inherited roots'),(s.Integer(2*len(roots)+repeat-1),'Add both exterior intervals and duplicate the bounded-gap count'),(s.Integer(len(roots)+2*repeat),'Count every inherited repeated root twice')],[T('Let the distinct displayed roots be denoted by the corresponding root symbols, with their displayed positive multiplicities.'),r'(r_1,\ldots,r_{'+str(len(roots))+r'})=('+','.join(map(str,roots))+r'),\quad(m_1,\ldots,m_{'+str(len(mult))+r'})=('+','.join(map(str,mult))+r')',r'\frac{P\prime(x)}{P(x)}=\sum_{j=1}^{'+str(len(roots))+r'}\frac{m_j}{x-r_j},\qquad\left(\frac{P\prime}{P}\right)\prime=-\sum_j\frac{m_j}{(x-r_j)^2}<0',T('The symbols are the displayed distinct roots and their positive multiplicities. Each bounded gap contributes one solution; exactly one exterior gap contributes because the constant has a fixed nonzero sign.'),r'\textnormal{Solutions away from the roots: }'+str(len(roots)-1)+r'+1='+str(len(roots)),T('A displayed root of multiplicity at least two remains a root of the derivative equation, with multiplicity reduced by one.'),r'\textnormal{Inherited distinct roots: }'+str(repeat),r'\textnormal{Total: }'+str(len(roots))+'+'+str(repeat)+'='+L(A)],'log-derivative-global-pole-root-count','nonnegative-integer')

@register('differentiation','schwarz-pick-jet','disk-map-sharp-second-jet','two-Schur-normalizations-and-extremal-Blaschke-map','A sharp second derivative with a fixed first jet needs two disk normalizations, a shifted derivative disk, and an attaining analytic map.','The real polynomial uniform-norm problem uses alternation; this bound comes from complex disk geometry.',[{'caseId':'a-'+str(a)+'-c-'+str(c),'a':str(a),'c':str(c),'purpose':'Change both the center value and the fixed first-jet constraint.'} for a,c in [(R(1,4),R(1,3)),(R(1,3),R(1,2)),(R(1,2),R(1,4)),(R(2,3),R(1,3)),(R(3,4),R(1,2)),(R(1,5),R(2,3)),(R(2,5),R(3,4)),(R(3,5),R(2,3))]],['complex analytic disk maps','Schwarz lemma','chain rule','extremal construction'])
def schwarz(case):
 a=R(case['a']);c=R(case['c']);b=(1-a*a)*c;A=2*(1-a*a)*(1-c*c+a*c*c);h=(c-z)/(1-c*z);f=(a+z*h)/(1+a*z*h)
 ck('The explicit extremizer has the prescribed center value',f.subs(z,0),a);ck('The explicit extremizer has the prescribed first derivative',s.diff(f,z).subs(z,0),b);ck('The extremizer attains the negative endpoint of the derivative disk',s.diff(f,z,2).subs(z,0),-A)
 v=s.symbols('v');g=z*(c+v*z);trial=(a+g)/(1+a*g);ck('The general second-jet transformation has the stated center and scale',s.diff(trial,z,2).subs(z,0),2*(1-a*a)*(v-a*c*c))
 analytic('Two applications of Schwarz lemma',['The map is analytic from the open unit disk into itself; the specified real center and first-jet parameters are strictly between zero and one.'],['The disk automorphism (f-a)/(1-af) vanishes at zero, so it equals z h(z) for another disk map h with h(0)=c. Applying Schwarz lemma after normalizing h at c gives |h prime(0)|<=1-c^2.','Solving for f gives f second(0)=2(1-a^2)(h prime(0)-a c^2). The farthest point of the allowed derivative disk has modulus2(1-a^2)(1-c^2+a c^2).','The Blaschke factor h(z)=(c-z)/(1-cz) reaches the farthest negative direction, and the reconstructed f maps the disk into itself and attains the bound.'])
 return candidate(T('Let f be analytic on the open complex unit disk, with ')+r'|f(z)|<1,\quad f(0)='+L(a)+r',\quad f\prime(0)='+L(b)+r'.'+T('What is the largest possible value of ')+r'|f^{\prime\prime}(0)|?',A,[(2*(1-a*a)*(1-c*c),'Ignore the nonzero center of the second-derivative disk'),(2*(1-a*a),'Ignore the first-derivative restriction'),(2*(1-a*a)*(1-c*c-a*c*c),'Subtract the center distance rather than add it when maximizing modulus'),((1-a*a)*(1-c*c+a*c*c),'Forget that the quadratic coefficient is half the second derivative'),(2*(1-a)*(1-c*c+a*c*c),'Use an incorrect derivative for the first disk automorphism'),(2*(1-a*a)*(1+c*c),'Reverse the Schwarz-Pick subtraction'),(2*(1-a*a)*(1-b*b+a*b*b),'Use the unnormalized first derivative as the center of the second disk map'),(2*(1-a*a)*(1-c*c+a*a*c*c),'Square the center in the translation term'),(2*(1-a*a)*(1-c*c+a*c),'Lose one factor of the fixed first jet in the translation term'),(2*(1-a*a)*(1-c*c)/(1+a*c*c),'Replace the affine jet relation by an erroneous fractional relation')],[r'a='+L(a)+r',\quad c='+L(c)+r',\qquad\frac{f(z)-a}{1-af(z)}=zh(z),\quad h(0)=c',T('Schwarz lemma gives a disk map after dividing the first normalized map by the coordinate. Normalize once more at its nonzero center.'),r'|h\prime(0)|\le1-c^2,\qquad f^{\prime\prime}(0)=2(1-a^2)(h\prime(0)-ac^2)',r'|f^{\prime\prime}(0)|\le2(1-a^2)(1-c^2+ac^2)='+L(A),r'h(z)=\frac{c-z}{1-cz},\qquad f(z)=\frac{a+zh(z)}{1+azh(z)}',T('This explicit disk map satisfies the prescribed data and reaches the bound, so it is a maximum.')],'sharp-complex-disk-second-jet','nonnegative-rational')

@register('differentiation','exponential-chebyshev-zero-bound','real-exponential-polynomial-Chebyshev-system','weighted-Rolle-induction-and-sharp-interpolation','The nonoscillatory exponential space has a sharp global zero bound, which must be proved and attained rather than inferred from a polynomial degree.','The Sturm-Hurwitz construction forces a minimum number of periodic zeros by orthogonality; this bounds a maximum on the real line by weighted Rolle arguments.',[{'caseId':'degrees-'+str(i),'degrees':ds,'rates':rs,'purpose':'Vary polynomial multiplicities and real exponential modes, including a zero-rate mode.'} for i,(ds,rs) in enumerate([([1,2],[-1,2]),([0,1,2],[-2,0,3]),([2,2],[1,4]),([1,1,1],[-3,1,2]),([0,2,3],[-1,2,5]),([2,0,1,0],[-4,-1,0,3]),([3,1,2],[0,1,4]),([1,2,0,2],[-2,1,3,6])])],['Rolle theorem','multiplicity','linear algebra','exponential functions'])
def cheb_zeros(case):
 ds=case['degrees'];rs=case['rates'];dim=sum(d+1 for d in ds);A=s.Integer(dim-1);basis=[x**j*s.exp(rate*x) for d,rate in zip(ds,rs) for j in range(d+1)]
 W=s.Matrix([[s.diff(f,x,i).subs(x,0) for f in basis] for i in range(dim)])
 condition('The independent confluent exponential jet matrix is invertible',W.det()!=0,'The displayed real rates are distinct and the basis has exactly the stated dimension.')
 for d,rate in zip(ds[1:],rs[1:]):
  f=x**d*s.exp((rate-rs[0])*x);g=s.diff(f,x,ds[0]+1)/s.exp((rate-rs[0])*x)
  ck('Weighted differentiation preserves a remaining polynomial mode degree',s.degree(s.simplify(g),x),d)
 analytic('Extended real Chebyshev-system zero bound',['All rates are real and pairwise distinct; polynomial degrees are bounded as stated; the zero function is excluded.'],['Multiply by the positive exponential corresponding to the negative of the first rate. Differentiating one more time than the first polynomial degree removes that mode. Weighted Rolle loses at most that many zeros, counted with multiplicity.','Every remaining rate differs from the removed one, so the leading polynomial coefficient remains nonzero under this derivative operation. Induction on the number of exponential modes yields at most dimension minus one real zeros.','For sharpness, impose zeros at any dimension-minus-one distinct real points. There are fewer homogeneous linear equations than coefficients, so a nonzero coefficient vector exists. The zero bound and independence ensure a nonzero function with exactly those distinct zeros.'])
 statement=r'f(x)=\sum_{j=1}^{'+str(len(ds))+r'}P_j(x)e^{\lambda_jx},\qquad(\lambda_1,\ldots,\lambda_{'+str(len(ds))+r'})=('+','.join(map(str,rs))+r'),\qquad(\deg P_1,\ldots,\deg P_{'+str(len(ds))+r'})\le('+','.join(map(str,ds))+r').'
 return candidate(statement+T('The degree bounds are componentwise. The real polynomials may have smaller degree or be zero, but f is not identically zero. What is the largest possible number of distinct real zeros of f?'),A,[(s.Integer(dim),'Count one more zero than the dimension permits'),(s.Integer(sum(ds)),'Ignore the independent constant term in each exponential mode'),(s.Integer(max(ds)),'Use only the largest polynomial degree'),(s.Integer(2*dim-1),'Treat real exponential modes as oscillatory pairs'),(s.oo,'Confuse real exponentials with trigonometric oscillation'),(s.Integer(dim+len(ds)-1),'Count each exponential factor as an additional polynomial degree')],[T('Let the displayed upper degree bounds be denoted by the corresponding d symbols.'),r'D=\sum_{j=1}^{'+str(len(ds))+r'}(d_j+1)='+str(dim),T('Remove one exponential factor, then differentiate enough times to eliminate its polynomial. Weighted Rolle transfers a hypothetical excessive zero count to a space with one fewer exponential mode.'),T('Every remaining exponential rate is different, so differentiation preserves its polynomial degree. Induction bounds the zero count by the dimension minus one.'),r'\#\{x\in\mathbb R:f(x)=0\}\le D-1='+L(A),T('To attain the bound, prescribe that many distinct real zeros. The corresponding homogeneous linear system has fewer equations than coefficients, so a nonzero function exists. The proved bound prevents further zeros or multiplicities.')],'sharp-real-exponential-polynomial-zero-count','nonnegative-integer')
